class Solution { public:vector<vector<int>> differenceOfDistinctValues(vector<vector<int>>& grid){int rows=grid.size(),cols=grid[0].size();vector answer(rows,vector<int>(cols));for(int row=0;row<rows;++row)for(int col=0;col<cols;++col){unordered_set<int> topLeft,bottomRight;for(int r=row-1,c=col-1;r>=0&&c>=0;--r,--c)topLeft.insert(grid[r][c]);for(int r=row+1,c=col+1;r<rows&&c<cols;++r,++c)bottomRight.insert(grid[r][c]);answer[row][col]=abs((int)topLeft.size()-(int)bottomRight.size());}return answer;} };
